186	/**
187	 * @brief user_data 是否可能是可读的页名字符串（老 DashboardView 的约定）。
188	 *
189	 * @note ⚠ 本工程大量控件把**整数标签/对象指针**存在 user_data 里
190	 *       （`helm_widget.c`: `HELM_MSW_ON_TAG = 0x48535732` 等）。旧代码直接
191	 *       `page_id[0]` 解引用 ⇒ 标签被当地址读，PRECISERR。
192	 *       2026-10-18 现场：设置页里有 ON 开关，KEY2 前的焦点扫描崩在 0x48535732
193	 *       （cfsr=0x8200 bfar=0x48535732 pc=lv_port_is_nav_button:195）。
194	 *       这里先确认指针落在本板可读区，且后面留得下最长页名，再解引用。
195	 */
196	static bool lv_port_user_data_str_ok(const void * ptr)
197	{
198	    uintptr_t a = (uintptr_t)ptr;
199	    uintptr_t end;
200	
201	    /* 与 nuttx.map / MPU 配置一致：内部 flash（4 MiB）、HCPU SRAM、PSRAM。 */
202	    if (a >= 0x10000000u && a < 0x10400000u) {
203	        end = 0x10400000u;
204	    } else if (a >= 0x20000000u && a < 0x20280000u) {
205	        end = 0x20280000u;
206	    } else if (a >= 0x60000000u && a < 0x62000000u) {
207	        end = 0x62000000u;
208	    } else {
209	        return false;
210	    }
211	
212	    /* 页名很短；留 32 字节窗口，避免指针贴着可读区末尾时扫出去。 */
213	    return (end - a) >= 33u;
214	}
