216	static bool lv_port_is_nav_button(lv_obj_t *obj)
217	{
218	    const char *page_id;
219	    uint32_t i;
220	
221	    if (!lv_port_is_focus_candidate(obj) || lv_port_has_focus_candidate_child(obj)) {
222	        return false;
223	    }
224	
225	    page_id = (const char *)lv_obj_get_user_data(obj);
226	    if (page_id == NULL || !lv_port_user_data_str_ok(page_id) ||
227	        page_id[0] == '\0') {
228	        return false;
229	    }
230	
231	    /* DashboardView::btnCreate stores a page name string in user_data. */
232	    for (i = 0; i < 32u; i++) {
233	        unsigned char c = (unsigned char)page_id[i];
234	
235	        if (c == '\0') {
236	            return true;
237	        }
238	
239	        if (!isalnum(c)) {
240	            return false;
241	        }
242	    }
243	
244	    return false;   /* 32 字节还没结束：不是页名 */
245	}
