247	static void lv_port_collect_nav_buttons(lv_obj_t *root, uint32_t *n)
248	{
249	    uint32_t i;
250	    uint32_t cnt;
251	
252	    if (root == NULL || *n >= LV_PORT_FOCUS_MAX) {
253	        return;
254	    }
255	
256	    if (lv_port_is_nav_button(root)) {
257	        s_ctx.focus_items[(*n)++] = root;
258	        return;
259	    }
260	
261	    cnt = lv_obj_get_child_count(root);
262	    for (i = 0; i < cnt; i++) {
263	        lv_port_collect_nav_buttons(lv_obj_get_child(root, i), n);
264	    }
265	}
