267	static bool lv_port_focus_still_valid(void)
268	{
269	    lv_obj_t *scr = lv_screen_active();
270	    uint32_t i;
271	
272	    if (s_ctx.focused == NULL || scr == NULL) {
273	        return false;
274	    }
275	
276	    for (i = 0; i < s_ctx.focus_count; i++) {
277	        if (s_ctx.focus_items[i] == s_ctx.focused) {
