286	static void lv_port_focus_apply(int index)
287	{
288	    if (s_ctx.focused != NULL) {
289	        lv_obj_clear_state(s_ctx.focused, LV_STATE_FOCUSED);
290	    }
291	
292	    if (s_ctx.focus_count == 0) {
293	        s_ctx.focused = NULL;
294	        s_ctx.focus_index = -1;
295	        s_ctx.focus_ready = false;
296	        return;
297	    }
298	
299	    if (index < 0) {
300	        index = 0;
301	    }
302	    if ((uint32_t)index >= s_ctx.focus_count) {
303	        index = (int)s_ctx.focus_count - 1;
304	    }
305	
306	    s_ctx.focus_index = index;
307	    s_ctx.focused = s_ctx.focus_items[index];
308	    lv_obj_add_state(s_ctx.focused, LV_STATE_FOCUSED);
309	    s_ctx.focus_ready = true;
310	}
