312	static void lv_port_focus_sync(void)
313	{
314	    lv_obj_t *scr;
315	    lv_obj_t *prev = s_ctx.focused;
316	    uint32_t n = 0;
317	    uint32_t i;
318	    int keep_index = -1;
319	
320	    scr = lv_screen_active();
321	    if (scr == NULL) {
322	        s_ctx.focus_count = 0;
323	        s_ctx.focus_ready = false;
324	        s_ctx.focused = NULL;
325	        return;
326	    }
327	
328	    lv_port_collect_nav_buttons(scr, &n);
329	    s_ctx.focus_count = n;
330	
331	    if (prev != NULL) {
332	        for (i = 0; i < n; i++) {
333	            if (s_ctx.focus_items[i] == prev) {
334	                keep_index = (int)i;
335	                break;
336	            }
337	        }
338	    }
339	
340	    if (n == 0) {
341	        if (prev != NULL) {
342	            lv_obj_clear_state(prev, LV_STATE_FOCUSED);
343	        }
344	        s_ctx.focused = NULL;
345	        s_ctx.focus_index = -1;
346	        s_ctx.focus_ready = false;
347	        return;
348	    }
349	
350	    if (keep_index < 0) {
351	        keep_index = 0;
352	    }
353	
354	    lv_port_focus_apply(keep_index);
355	}
