884	 */
885	void lv_port_buttons_init(void)
886	{
887	    if (s_ctx.disp != NULL) {
888	        return;
889	    }
890	
891	    s_ctx.fd = open(LV_PORT_BTN_PATH, O_RDONLY | O_NONBLOCK);
892	    if (s_ctx.fd < 0) {
893	        BTN_LOG("open %s failed errno=%d", LV_PORT_BTN_PATH, errno);
894	        LV_LOG_WARN("btn: open %s failed (%d)", LV_PORT_BTN_PATH, errno);
895	        return;
896	    }
897	
898	    s_ctx.disp = lv_display_get_default();
899	    if (s_ctx.disp == NULL) {
900	        close(s_ctx.fd);
901	        s_ctx.fd = -1;
902	        return;
903	    }
904	
905	    s_ctx.last = lv_port_btn_read();
906	    /* 开机时用户可能还按着 PWR，不能把这次当单击或 2s 关机。 */
907	    s_ctx.pwr_long_fired = (s_ctx.last & LV_PORT_BTN_PWR) != 0;
908	    s_ctx.pwr_press_tick = lv_tick_get();
909	    s_ctx.focus_index = -1;
910	
911	    s_ctx.pointer = lv_indev_create();
912	    lv_indev_set_type(s_ctx.pointer, LV_INDEV_TYPE_POINTER);
913	    lv_indev_set_display(s_ctx.pointer, s_ctx.disp);
914	    lv_indev_enable(s_ctx.pointer, false);
915	
916	    lv_timer_create(lv_port_btn_timer, LV_PORT_POLL_MS, NULL);
917	
918	    BTN_LOG("ready fd=%d KEY1=PA30 KEY2=PA33 PWR=PA34 last=0x%02x",
919	            s_ctx.fd, (unsigned)s_ctx.last);
920	    LV_LOG_INFO("btn: KEY1=PA30 KEY2=PA33 PWR=PA34 (click=bl, long 2s=off)");
921	}
