101	    from = (int)s_bl_ramp_from;
102	    to = (int)s_bl_ramp_to;
103	    if (e >= HELM_PWR_BL_RAMP_MS) {
104	        (void)BSP_LCD_BL_PwmPct(s_bl_ramp_to);
105	        s_bl_ramp_tmr = NULL;
106	        lv_timer_delete(t);
107	        return;
108	    }
109	
110	    v = from + (int)(((int32_t)(to - from) * (int32_t)e) /
111	                     (int32_t)HELM_PWR_BL_RAMP_MS);
112	    if (v < 0) {
113	        v = 0;
114	    } else if (v > 100) {
115	        v = 100;
116	    }
117	
118	    (void)BSP_LCD_BL_PwmPct((uint8_t)v);
119	}
