121	static void helm_pwr_bl_ramp_to(uint8_t pwm)
122	{
123	    uint8_t cur = BSP_LCD_BL_GetPct();
124	    uint8_t maxv = BSP_LCD_BL_GetMaxPct();
125	
126	    if (maxv != 0 && pwm > maxv) {
127	        pwm = maxv;
128	    }
129	
130	    s_bl_ramp_from = cur;
131	    s_bl_ramp_to = pwm;
132	    s_bl_ramp_t0 = lv_tick_get();
133	    if (cur == pwm) {
134	        helm_pwr_bl_ramp_stop();
135	        (void)BSP_LCD_BL_PwmPct(pwm);
136	        return;
137	    }
138	
139	    if (s_bl_ramp_tmr != NULL) {
140	        lv_timer_reset(s_bl_ramp_tmr);
141	        return;
142	    }
143	
144	    s_bl_ramp_tmr = lv_timer_create(helm_pwr_bl_ramp_cb,
145	                                    HELM_PWR_BL_RAMP_TICK_MS, NULL);
146	}
