191	static uint8_t helm_pwr_pwm_to_ui(uint8_t pwm)
192	{
193	    uint8_t maxv = myvendor_devctl_bl_max();
194	    uint8_t ui;
195	
196	    if (maxv == 0) {
197	        maxv = 80;
198	    }
199	
200	    ui = (uint8_t)(((unsigned)pwm * 100u) / (unsigned)maxv);
201	    if (ui > 100) {
202	        ui = 100;
203	    }
204	
205	    return (uint8_t)(ui / HELM_PWR_BL_UI_STEP * HELM_PWR_BL_UI_STEP);
206	}
