214	/** @brief UI 百分比换成要下发的 PWM。 */
215	uint8_t helm_pwr_ui_to_pwm(uint8_t ui)
216	{
217	    uint8_t maxv = myvendor_devctl_bl_max();
218	
219	    if (maxv == 0) {
220	        maxv = 80;
221	    }
222	
223	    if (ui > 100) {
224	        ui = 100;
225	    }
226	
227	    return (uint8_t)(((unsigned)ui * (unsigned)maxv + 50u) / 100u);
228	}
229	
230	/** @brief 亮度 0→20→…→100→0，PWM 线性过渡。 */
231	uint8_t helm_pwr_bl_cycle(void)
232	{
233	    uint8_t ui = helm_pwr_bl_ui();
234	
235	    if (ui >= 100u) {
236	        ui = 0u;
237	    } else {
238	        ui = (uint8_t)(ui + HELM_PWR_BL_UI_STEP);
239	        if (ui > 100u) {
240	            ui = 100u;
241	        }
242	    }
243	
244	    (void)myvendor_devctl_bl_apply(helm_pwr_ui_to_pwm(ui));
245	    helm_pwr_bl_ramp_to(myvendor_devctl_bl_get());
246	    helm_pwr_bl_defer_commit();
247	    return ui;
248	}
