422	static void helm_pwr_off_tick(lv_timer_t *t)
423	{
424	    LV_UNUSED(t);
425	    helm_splash_pump(&s_off_sp);
426	
427	    switch (s_off_step) {
428	    case HELM_PWR_OFF_ENTER:
429	        if (lv_tick_elaps(s_off_t0) < HELM_PWR_OFF_ENTER_MS) {
430	            return;
431	        }
432	
433	        s_off_chore = 0;
434	        s_off_step = HELM_PWR_OFF_SLIDE_IN;
435	        s_off_t0 = lv_tick_get();
436	        helm_pwr_slide_in(s_off_chore);
437	        return;
438	
439	    case HELM_PWR_OFF_SLIDE_IN:
440	        if (lv_tick_elaps(s_off_t0) < HELM_PWR_OFF_SLIDE_MS) {
441	            return;
442	        }
443	
444	        s_off_step = HELM_PWR_OFF_RUN;
445	        return;
446	
447	    case HELM_PWR_OFF_RUN:
448	        helm_pwr_chore_run(s_off_chore);
449	        s_off_t0 = lv_tick_get();
450	        s_off_step = HELM_PWR_OFF_HOLD;
451	        return;
452	
453	    case HELM_PWR_OFF_HOLD:
454	        if (lv_tick_elaps(s_off_t0) < HELM_PWR_OFF_HOLD_MS) {
455	            return;
456	        }
457	
458	        s_off_step = HELM_PWR_OFF_SLIDE_OUT;
459	        s_off_t0 = lv_tick_get();
460	        helm_pwr_slide_out();
461	        return;
462	
463	    case HELM_PWR_OFF_SLIDE_OUT:
464	        if (lv_tick_elaps(s_off_t0) < HELM_PWR_OFF_SLIDE_MS) {
465	            return;
466	        }
467	
468	        if (s_off_chore < 2u) {
469	            s_off_chore++;
470	            s_off_step = HELM_PWR_OFF_SLIDE_IN;
471	            s_off_t0 = lv_tick_get();
472	            helm_pwr_slide_in(s_off_chore);
473	            return;
474	        }
475	
476	        s_off_step = HELM_PWR_OFF_BYE;
477	        s_off_t0 = lv_tick_get();
478	        helm_pwr_bye_begin();
479	        return;
480	
481	    case HELM_PWR_OFF_BYE:
482	        if (lv_tick_elaps(s_off_t0) < HELM_PWR_OFF_BYE_MS) {
483	            return;
484	        }
485	
486	        s_off_step = HELM_PWR_OFF_CUT;
487	        helm_pwr_paint_black();
488	        if (s_off_tmr != NULL) {
489	            lv_timer_delete(s_off_tmr);
490	            s_off_tmr = NULL;
491	        }
492	
493	        myvendor_devctl_power_cut();
494	        return;
495	
496	    default:
497	        return;
498	    }
499	}
