555	    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
556	    lv_anim_set_exec_cb(&a, helm_pwr_opa);
557	    lv_anim_start(&a);
558	
559	    s_off_step = HELM_PWR_OFF_ENTER;
