694	/** @brief 低电策略：约 10% 提示；约 3.05 V 存 GPX 后关机。 */
695	void helm_pwr_bat_tick(void)
696	{
697	    int pct;
698	    int mv;
699	    uint8_t pwr;
700	    bool charging;
701	    bool empty;
702	
703	    if (s_offing || myvendor_is_factory()) {
704	        return;
705	    }
706	
707	    if (!s_bat_armed) {
708	        s_bat_armed = true;
709	        s_bat_t0 = lv_tick_get();
710	        return;
711	    }
712	
713	    if (lv_tick_elaps(s_bat_t0) < HELM_PWR_BAT_GRACE_MS) {
714	        return;
715	    }
716	
717	    pct = myvendor_sys_battery_percent();
718	    mv = myvendor_sys_battery_mv();
719	    pwr = myvendor_sys_power_state();
720	    charging = (pwr == MYVENDOR_SYS_PWR_CHARGING);
721	    if (pct < 0 || mv < 0) {
722	        s_bat_off_hits = 0;
723	        return;
724	    }
725	
726	    if (charging) {
727	        s_bat_off_hits = 0;
728	        if (pct >= HELM_PWR_BAT_REARM_PCT) {
729	            s_bat_warned = false;
730	        }
731	
732	        return;
733	    }
734	
735	    if (pct >= HELM_PWR_BAT_REARM_PCT) {
736	        s_bat_warned = false;
737	        s_bat_off_hits = 0;
738	        return;
739	    }
740	
741	    empty = (pct <= HELM_PWR_BAT_OFF_PCT) || (mv <= HELM_PWR_BAT_OFF_MV);
742	    if (empty) {
743	        s_bat_off_hits++;
744	        if (s_bat_off_hits < HELM_PWR_BAT_OFF_HITS) {
745	            return;
746	        }
747	
748	        syslog(LOG_WARNING, "helm: low bat off pct=%d mv=%d", pct, mv);
749	        helm_pwr_exec_as("电量耗尽");
750	        return;
751	    }
752	
753	    s_bat_off_hits = 0;
754	    if (s_bat_warned || pct > HELM_PWR_BAT_WARN_PCT) {
755	        return;
756	    }
757	
758	    s_bat_warned = true;
759	    if (helm_idle_is_sleeping()) {
760	        helm_idle_wake();
761	    }
762	
763	    myvendor_sound_warn();
764	    lv_pm_notify_show_icon("电量低", "请尽快充电", HELM_ICO_BATT, 4000);
765	    syslog(LOG_INFO, "helm: low bat warn pct=%d mv=%d", pct, mv);
766	}
