/**
 * @brief 骑行/暂停中返回环形主页（R1-S4a）。
 * @details 只切视图，不动记录：`helm_riding()` 仍为 true、`s_sh.paused` 保持原值，
 *          REC 按状态栏既有规则（暂停灰 / 记录红）画。再进骑行由
 *          `helm_ring_enter(0)` / 右键长按清 `at_ring` 并 apply_view。
 */
static void helm_back_to_ring(void)
{
    if (!s_sh.attached) {
        return;
    }

    s_sh.at_ring = true;
    s_sh.view_anim = false;
    helm_apply_view();
    helm_refresh_numbers();
    helm_raise_chrome();
    printf("helm: back to ring ride=%d paused=%d\n",
           helm_riding() ? 1 : 0, s_sh.paused ? 1 : 0);
}

static void helm_on_next(void * ud)
{
    uint8_t n = helm_page_count();
    uint8_t * idx;
#if MYVENDOR_LVGL_STALL_LOG
    uint32_t t0;
#endif

    LV_UNUSED(ud);
    if (!s_sh.attached) {
        LVGL_STALL("helm_on_next drop !attached covered=%d",
            (int)s_sh.ui_covered);
        return;
    }

    /* 任意按键都算"有交互"：把待机页提示环的浮动重新叫醒（3 s 后再自停）。 */
    helm_sb_bob_kick();

    /* 环形主页（R1-S2）：短按 = 顺时针转一格，**不翻页**。 */
    if (s_sh.view_id == HELM_PAGE_RING) {
        printf("helm: ring KEY2 short rotate cw (mode=%u)\n",
               (unsigned)s_sh.ring_mode);
        helm_ring_rotate(1);
        return;
    }

    /* 演示页面锁：任意翻页键先解锁，本次按键继续走正常翻页（下面会 apply）。 */
    if (s_demo_page != (helm_page_id_t)0xff) {
        s_demo_page = (helm_page_id_t)0xff;
    }

#if MYVENDOR_LVGL_STALL_LOG
    t0 = lv_tick_get();
#endif
    if (helm_save_open()) {
        helm_obj_press(s_sh.save_mask);
        helm_save_clicked(NULL);
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        return;
    }

    /* 暂停态：KEY2 短 = 询问是否保存（复用现有 save_mask 卡片，外观不变）。 */
    if (s_sh.paused) {
        printf("helm: KEY2 short (paused) -> save ask\n");
        helm_prompt_save();
        return;
    }

    if (helm_flip_busy()) {
        LVGL_STALL("helm_on_next drop busy");
        return;
    }

    idx = helm_active_idx();
    *idx = (uint8_t)((*idx + 1u) % n);
    s_sh.view_dir = 1;
    s_sh.view_anim = true;
    LVGL_STALL("helm_on_next view=%u/%u riding=%d",
           (unsigned)*idx + 1u, (unsigned)n, helm_riding() ? 1 : 0);
    helm_apply_view();
    helm_flip_arm(helm_riding() ? HELM_FLIP_GUARD_MS : HELM_VIEW_MS);
    helm_nums_defer_begin();
    LVGL_STALL("helm_on_next done %ums",
        (unsigned)lv_tick_elaps(t0));
}

static void helm_on_menu(void * ud)
{
    LV_UNUSED(ud);
    if (!s_sh.attached) {
        return;
    }

    /* 任意按键都算"有交互"：把待机页提示环的浮动重新叫醒（3 s 后再自停）。 */
    helm_sb_bob_kick();

    if (helm_save_open()) {
        printf("helm: save mask closed by KEY1 long\n");
        helm_save_hide();
        myvendor_sound_back();
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        myvendor_sound_back();
        return;
    }

    /* 环形主页（R1-S2）：KEY1 长 = 进入当前模式。 */
    if (s_sh.view_id == HELM_PAGE_RING) {
        printf("helm: ring KEY1 long enter mode=%u\n",
               (unsigned)s_sh.ring_mode);
        helm_ring_enter((int)s_sh.ring_mode);
        return;
    }

    /* R1-S4a：骑行页 KEY1 长 = 返回环形（记录继续）；菜单只能从环形的
     * 「设置」模式进入，这里不再开菜单。暂停态 KEY1 长无动作。 */
    if (s_sh.paused) {
        printf("helm: KEY1 long ignored (paused)\n");
        return;
    }

    printf("helm: KEY1 long (ride page) -> back to ring\n");
    myvendor_sound_back();
    helm_back_to_ring();
}

void helm_shell_toggle_ride(void)
{
    const bicycle_runtime_t * rt = bicycle_runtime_get();

    if (!s_sh.attached) {
        printf("helm: KEY2 long ignored (not attached)\n");
        return;
    }

    if (helm_save_open()) {
        helm_save_clicked(NULL);
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        return;
    }

    printf("helm: KEY2 long ride toggle rec=%d paused=%d ring=%d home=%u ride=%u\n",
           (rt && rt->recording) ? 1 : 0, s_sh.paused ? 1 : 0,
           s_sh.at_ring ? 1 : 0,
           (unsigned)s_sh.home_idx, (unsigned)s_sh.ride_idx);

    /* 暂停态：KEY2 长 = 继续骑行（与旧 resume 同一条路径：map_page 继续 +
     * set_paused(false)）。若当前停在环形，恢复后进骑行页。 */
    if (s_sh.paused) {
        bool was_ring = s_sh.at_ring;

        printf("helm: KEY2 long resume ride%s\n", was_ring ? " (ring)" : "");
        helm_pause_resume_by_key();

        lv_obj_clear_flag(tick_l, LV_OBJ_FLAG_SCROLLABLE);
        s_sh.nav_scale_lab = helm_lab(s_sh.nav_scale, s_sh.font_title,
                                      HELM_COLOR_INK, "200m");
        {
            lv_obj_t * tick_r = lv_obj_create(s_sh.nav_scale);

            lv_obj_remove_style_all(tick_r);
            lv_obj_set_size(tick_r, 1, 6);
            lv_obj_set_style_bg_color(tick_r, helm_color(HELM_COLOR_INK), 0);
            lv_obj_set_style_bg_opa(tick_r, LV_OPA_COVER, 0);
            lv_obj_clear_flag(tick_r, LV_OBJ_FLAG_SCROLLABLE);
        }
    }
    lv_obj_align(s_sh.nav_scale, LV_ALIGN_BOTTOM_RIGHT, -6,
                 -(HELM_PAGE_H - HELM_MAP_CARD_Y) - 4);

    lv_obj_add_flag(s_sh.nav_sum, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(s_sh.nav_scale, LV_OBJ_FLAG_HIDDEN);
}

