158	    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
159	                          LV_FLEX_ALIGN_CENTER);
160	    lv_obj_set_style_pad_column(row, 1, 0);
161	    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);
162	
163	    out->ndigit = with_sec ? 6u : 4u;
164	    for (i = 0; i < out->ndigit; i++) {
