238	static void helm_idle_overlay_refresh(void)
239	{
240	    uint32_t elapsed;
241	    unsigned hh;
242	    unsigned mm;
243	    unsigned ss;
244	    struct tm tm_buf;
245	    char date[24];
246	
247	    if (!s_sleep || s_still.d[0] == NULL || s_clock.d[0] == NULL) {
248	        return;
249	    }
250	
251	    elapsed = lv_tick_elaps(s_enter_t0) / 1000u;
252	    if (elapsed > 99u * 3600u + 59u * 60u + 59u) {
253	        elapsed = 99u * 3600u + 59u * 60u + 59u;
254	    }
255	
256	    hh = elapsed / 3600u;
257	    mm = (elapsed / 60u) % 60u;
258	    ss = elapsed % 60u;
259	    helm_idle_hms_set(&s_still, hh, mm, ss, true);
260	
261	    if (helm_idle_wall_now(&tm_buf)) {
262	        helm_idle_hms_set(&s_clock, (unsigned)tm_buf.tm_hour,
263	                          (unsigned)tm_buf.tm_min, 0,
264	                          (tm_buf.tm_sec & 1) == 0);
265	        lv_snprintf(date, sizeof(date), "%d月%d日  %s",
266	                    tm_buf.tm_mon + 1, tm_buf.tm_mday,
267	                    s_wday[tm_buf.tm_wday % 7]);
268	        helm_idle_label_set(s_date_lab, date);
269	    } else {
270	        helm_idle_label_set(s_clock.d[0], "-");
271	        helm_idle_label_set(s_clock.d[1], "-");
272	        helm_idle_label_set(s_clock.d[2], "-");
273	        helm_idle_label_set(s_clock.d[3], "-");
274	        helm_idle_colon_opa(s_clock.colon[0], true);
275	        helm_idle_label_set(s_date_lab, "");
276	    }
277	}
