static bool helm_row_stays(const helm_row_t * r)
{
    if (r == NULL) {
        return false;
    }

    if (r->kind == HELM_KIND_SW || r->kind == HELM_KIND_VAL) {
        return true;
    }

    switch (r->act) {
    case ACT_SCAN_AUTO:
    case ACT_SCAN_CONNECT:
    case ACT_NAV_STOP:
    case ACT_NAV_SKIP:
    case ACT_NAV_NEAREST:
    case ACT_RIDES_CLEAR_ALL:

    case ACT_RIDE_DEL:
    case ACT_INBOX_OPEN:
        return true;
    default:
        return false;
    }
}

