static void helm_pwr_tap_timeout_cb(lv_timer_t * t)
{
    LV_UNUSED(t);

    s_tap_tmr = NULL;
    /* 窗口内没有第二击 ⇒ 这是单击：定稿语义"无动作"（亮度在设置里）。 */
    printf("helm: PWR single (no-op)\n");
