/** @brief PWR 单击：进 300 ms 双击窗口；窗口内第二击 ⇒ 双击休眠。 */
void helm_pwr_on_click(void)
{
    if (s_offing) {
        return;
    }

    if (s_mask != NULL) {
        helm_pwr_tap_cancel();
        helm_pwr_dialog_cancel();
        return;
    }

    if (s_tap_tmr != NULL) {
        helm_pwr_tap_cancel();
        printf("helm: PWR double -> sleep\n");
        helm_idle_force_enter();
        return;
    }

    s_tap_tmr = lv_timer_create(helm_pwr_tap_timeout_cb, HELM_PWR_DOUBLE_MS, NULL);
    if (s_tap_tmr != NULL) {
        lv_timer_set_repeat_count(s_tap_tmr, 1);
    }
}

