/* ── 两段式保存（R1-S4b）──────────────────────────────────────────────────
 * 第一段 = 现有 save_mask（左=不保存 / 右=保存）；保存/丢弃**先**走原有
 * `helm_finish_ride(true/false)`（GPX commit/discard 顺序不变），**然后**才弹
 * 第二段结果卡（已保存/未保存 + 里程/时长/均速，只展示）。关闭后回环形页。 */
static bool helm_save_done_active(void)
{
    return s_sh.save_done_open;
}

/** @brief 第一段点键前抓本次摘要（finish 会结束 session，之后读不到）。 */
typedef struct {
    uint64_t ms;
    float km;
    float avg;
} helm_ride_sum_t;

static helm_ride_sum_t s_ride_sum;

static void helm_ride_sum_capture(void)
{
    const bicycle_runtime_t * rt = bicycle_runtime_get();

    s_ride_sum.ms = rt ? rt->session_elapsed_ms : 0ull;
    s_ride_sum.km = rt ? (float)(rt->session_distance_m / 1000.0) : 0.0f;
    s_ride_sum.avg = helm_avg_kph(rt);
}

static void helm_save_done_show(bool saved)
{
    char buf[24];
    char line[32];

    if (s_sh.save_done_mask == NULL) {
        return;
    }

    s_sh.save_done_saved = saved;
    helm_label_set(s_sh.save_done_title, saved ? "已保存" : "未保存");
    helm_label_set(s_sh.save_done_hint,
                   saved ? "记录已写入本机" : "本次数据未写入");

    helm_fmt_hms(buf, sizeof(buf), s_ride_sum.ms);
    helm_label_set(s_sh.save_done_time, buf);

    helm_fmt_km(buf, sizeof(buf), s_ride_sum.km);
    lv_snprintf(line, sizeof(line), "%s km", buf);
    helm_label_set(s_sh.save_done_dist, line);

    helm_fmt_speed(buf, sizeof(buf), s_ride_sum.avg);
    helm_label_set(s_sh.save_done_avg, buf);

    s_sh.save_done_open = true;
    lv_obj_clear_flag(s_sh.save_done_mask, LV_OBJ_FLAG_HIDDEN);
    lv_obj_move_foreground(s_sh.save_done_mask);
    helm_obj_stagger_in(s_sh.save_done_mask);
    printf("helm: save stage2 saved=%d dist=%.1f km t=%.1f min avg=%.1f km/h\n",
           saved ? 1 : 0, (double)s_ride_sum.km,
           (double)((float)s_ride_sum.ms / 60000.0f), (double)s_ride_sum.avg);
}

/** @brief 第二段关闭：只收卡片并回环形（记录已在第一段结束）。 */
static void helm_save_done_close(void)
{
    if (!s_sh.save_done_open) {
        return;
    }

    s_sh.save_done_open = false;
    if (s_sh.save_done_mask != NULL) {
        lv_obj_add_flag(s_sh.save_done_mask, LV_OBJ_FLAG_HIDDEN);
    }

    printf("helm: save stage2 closed -> ring\n");
    myvendor_sound_back();
    helm_back_to_ring();
