/** @brief 递归打印 label 文案（保存两段卡的断言读 `[save] text` / `[save2] text`）。 */
static void helm_save_dump_texts(const char * tag, lv_obj_t * obj)
{
    uint32_t i;
    uint32_t n;

    if (obj == NULL) {
        return;
    }

    if (lv_obj_check_type(obj, &lv_label_class)) {
        const char * txt = lv_label_get_text(obj);

        if (txt != NULL && txt[0] != '\0') {
            printf("[%s] text %s\n", tag, txt);
        }
    }

    n = lv_obj_get_child_count(obj);
    for (i = 0; i < n; i++) {
        helm_save_dump_texts(tag, lv_obj_get_child(obj, i));
    }
}

static void helm_save_dump_cap(const char * tag, lv_obj_t * keys, bool right)
{
    lv_obj_t * cap;
    lv_obj_t * act;
    lv_obj_t * cap_lab;
    lv_area_t c;
    const char * txt;

    helm_keyillus_get(keys, right, &cap, &act);
    if (cap == NULL) {
        printf("[%s] %s_cap=null\n", tag, right ? "right" : "left");
        return;
    }

    lv_obj_get_coords(cap, &c);
    printf("[%s] %s_cap=%d,%d,%d,%d\n", tag, right ? "right" : "left",
           (int)c.x1, (int)c.y1, (int)c.x2, (int)c.y2);

    cap_lab = lv_obj_get_child(cap, 0);
    txt = (cap_lab != NULL) ? lv_label_get_text(cap_lab) : NULL;
    printf("[%s] %s_cap_txt=%s\n", tag, right ? "right" : "left",
           txt != NULL ? txt : "");

    txt = (act != NULL) ? lv_label_get_text(act) : NULL;
    printf("[%s] %s_act=%s\n", tag, right ? "right" : "left",
           txt != NULL ? txt : "");
}

