static int gpx_port_file_plant_empty(const char *path)
{
  unsigned n = 0;

  if (path == NULL || path[0] == '\0')
    {
      return -EINVAL;
    }

  for (;;)
    {
      int fd;

      myvendor_watchdog_hw_pet();
      fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0666);
      if (fd >= 0)
        {
