    if (s_ride_sum.ms > 0ull) {
        double hours = (double)s_ride_sum.ms / 3600000.0;

        s_ride_sum.avg = (float)((double)s_ride_sum.km / hours);
    } else {
        s_ride_sum.avg = 0.0f;
    }
}

